package com.nyayaconnect.auth;
import com.nyayaconnect.common.*; import com.nyayaconnect.security.*; import com.nyayaconnect.user.*; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException; import java.util.Map;
public class LoginServlet extends HttpServlet { private UserService users; public void init(){users=SpringAccess.bean(getServletContext(),UserService.class);}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{String throttleKey=req.getRemoteAddr()==null?"unknown":req.getRemoteAddr();try{if(LoginRateLimiter.isLimited(throttleKey)){res.setHeader("Retry-After","900");Api.error(res,429,"LOGIN_RATE_LIMITED","Too many sign-in attempts. Please try again later.");return;}Map<?,?> b=Json.MAPPER.readValue(req.getInputStream(),Map.class);String email=get(b,"email");String pw=get(b,"password");User u=users.authenticate(email.trim().toLowerCase(),pw);LoginRateLimiter.success(throttleKey);HttpSession old=req.getSession(false);if(old!=null)old.invalidate();HttpSession s=req.getSession(true);s.setAttribute(AuthenticationFilter.SESSION_KEY,new SessionUser(u.id(),u.name(),u.email(),u.role()));s.setAttribute(CsrfFilter.SESSION_KEY,CsrfFilter.issue());s.setMaxInactiveInterval(1800);Api.json(res,200,Map.of("user",s.getAttribute(AuthenticationFilter.SESSION_KEY),"csrfToken",s.getAttribute(CsrfFilter.SESSION_KEY)));}catch(SecurityException e){LoginRateLimiter.failure(throttleKey);Api.error(res,401,"INVALID_CREDENTIALS","Invalid email or password.");}catch(Exception e){Api.error(res,400,"INVALID_REQUEST","Invalid login request.");}}
 private static String get(Map<?,?> m,String k){return get(m,k,"");}
 private static String get(Map<?,?> m,String k,String d){Object v=m.get(k);return v==null?d:String.valueOf(v);}
}
